package agentvault

import (
	"encoding/base64"
	"net/http"
	"testing"
)

// undici, urllib, requests and libcurl only send Proxy-Authorization when both halves are present, and
// git refuses to start without a password at all, so the token has to ride in one of a filled pair. It
// is the password half: tools mask that one and print the username, and a token containing a colon
// survives there because the split takes the first one only.
func TestRequestSessionTokenReadsThePasswordHalf(t *testing.T) {
	basic := func(user, pass string) *http.Request {
		r, _ := http.NewRequest(http.MethodConnect, "https://example.com/", nil)
		r.Header.Set("Proxy-Authorization", "Basic "+base64.StdEncoding.EncodeToString([]byte(user+":"+pass)))
		return r
	}

	for _, tc := range []struct {
		name, user, pass, want string
	}{
		{"the shape agent-vault run hands out", ProxyAuthUsername, "agv_tok", "agv_tok"},
		{"a token carrying a colon", ProxyAuthUsername, "agv_a:b", "agv_a:b"},
		{"the username is ignored", "someone-else", "agv_tok", "agv_tok"},
	} {
		got, ok := requestSessionToken(basic(tc.user, tc.pass))
		if !ok || got != tc.want {
			t.Fatalf("%s: got %q ok=%v, want %q", tc.name, got, ok, tc.want)
		}
	}

	if _, ok := requestSessionToken(basic("agv_tok", "")); ok {
		t.Fatal("an empty password half must not authenticate")
	}
}

package agentproxy

import (
	"fmt"
	"testing"
	"time"
)

// When the cache is full, inserting a new scope must evict the least-recently-seen entry (keeping
// actively-used agents cached) rather than reject the new one or grow the map without bound.
func TestAgentCacheEvictsLeastRecentlySeenWhenFull(t *testing.T) {
	a := newAgentCache(func() string { return "" }, newLeaseStore(func() string { return "" }))

	base := time.Now()
	for i := 0; i < maxAgentCacheEntries; i++ {
		// k0 is the most recently seen (active); higher indices are progressively staler, all well
		// within agentInactiveTTL so the inactive-cleanup pass leaves them alone and LRU decides.
		a.entries[fmt.Sprintf("k%d", i)] = &agentEntry{lastSeen: base.Add(-time.Duration(i) * time.Millisecond)}
	}

	active := "k0"
	oldest := fmt.Sprintf("k%d", maxAgentCacheEntries-1)

	a.evictIfFullLocked("new-scope")

	if len(a.entries) >= maxAgentCacheEntries {
		t.Fatalf("expected room for a new entry after eviction, still have %d", len(a.entries))
	}
	if _, ok := a.entries[oldest]; ok {
		t.Fatalf("expected least-recently-seen entry %q to be evicted", oldest)
	}
	if _, ok := a.entries[active]; !ok {
		t.Fatalf("expected active entry %q to survive eviction", active)
	}
}

// A key already present must not trigger eviction — updating an existing scope isn't growth.
func TestAgentCacheNoEvictionWhenReplacing(t *testing.T) {
	a := newAgentCache(func() string { return "" }, newLeaseStore(func() string { return "" }))

	base := time.Now()
	for i := 0; i < maxAgentCacheEntries; i++ {
		a.entries[fmt.Sprintf("k%d", i)] = &agentEntry{lastSeen: base.Add(-time.Duration(i) * time.Millisecond)}
	}

	a.evictIfFullLocked("k5")

	if len(a.entries) != maxAgentCacheEntries {
		t.Fatalf("expected no eviction when replacing an existing key, size changed to %d", len(a.entries))
	}
}

package agentvault

import (
	"errors"
	"fmt"
	"sync"
	"testing"
	"time"

	"github.com/Infisical/infisical-merge/packages/api"
)

type stubResolver struct {
	mu       sync.Mutex
	calls    int
	result   *resolveResult
	err      error
	delay    time.Duration
	lastHeld *sessionLogGrant
}

func (s *stubResolver) resolve(_ string, held *sessionLogGrant) (*resolveResult, error) {
	s.mu.Lock()
	s.calls++
	s.lastHeld = held
	result, err, delay := s.result, s.err, s.delay
	s.mu.Unlock()
	time.Sleep(delay)
	if err != nil {
		return nil, err
	}
	return result, nil
}

func (s *stubResolver) callCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.calls
}

func serviceWithSecret(secret string) *resolvedService {
	return &resolvedService{
		id:           "c1",
		name:         "svc",
		hostPatterns: parseHostPatterns("api.foo.com"),
		credential:   credential{kind: credentialBearer, value: []byte(secret)},
	}
}

func newTestCache(resolver sessionResolver) *sessionCache {
	return newSessionCache(resolver, func() time.Duration { return time.Minute })
}

func TestCacheKeyIsTheTokenHashNotTheToken(t *testing.T) {
	token := "agv_super_secret_session_token"
	resolver := &stubResolver{result: &resolveResult{SessionID: "s1", Services: []*resolvedService{serviceWithSecret("v")}}}
	cache := newTestCache(resolver)

	if _, err := cache.get(token); err != nil {
		t.Fatalf("get: %v", err)
	}

	for key := range cache.entries {
		if key == token {
			t.Fatal("the raw session token is being used as a cache key")
		}
	}
	if _, ok := cache.entries[sessionKey(token)]; !ok {
		t.Fatal("the entry should be keyed by the token hash")
	}
}

func TestExpiredSessionIsDroppedWithoutACall(t *testing.T) {
	past := time.Now().Add(-time.Minute)
	resolver := &stubResolver{result: &resolveResult{SessionID: "s1", ExpiresAt: &past}}
	cache := newTestCache(resolver)

	if _, err := cache.get("agv_token"); err != nil {
		t.Fatalf("first get: %v", err)
	}
	callsAfterFirst := resolver.calls

	if _, err := cache.get("agv_token"); !errors.Is(err, errSessionGone) {
		t.Fatalf("expected the session to be gone, got %v", err)
	}
	if resolver.calls != callsAfterFirst {
		t.Fatalf("an expired entry should be dropped without a call; calls went %d -> %d", callsAfterFirst, resolver.calls)
	}
}

func TestRefreshDropsAGoneSessionImmediately(t *testing.T) {
	for _, status := range []int{401, 404} {
		t.Run(map[int]string{401: "revoked or expired", 404: "actor deleted or org mismatch"}[status], func(t *testing.T) {
			resolver := &stubResolver{result: &resolveResult{SessionID: "s1", Services: []*resolvedService{serviceWithSecret("v")}}}
			cache := newTestCache(resolver)
			if _, err := cache.get("agv_token"); err != nil {
				t.Fatalf("get: %v", err)
			}

			resolver.err = &api.APIError{StatusCode: status, Name: map[int]string{401: infisicalUnauthorizedName, 404: infisicalNotFoundName}[status]}
			cache.refresh()

			if len(cache.entries) != 0 {
				t.Fatalf("a %d should drop the session now, %d entries remain", status, len(cache.entries))
			}
		})
	}
}

func TestRefreshKeepsServingWhileInfisicalIsUnreachable(t *testing.T) {
	resolver := &stubResolver{result: &resolveResult{SessionID: "s1", Services: []*resolvedService{serviceWithSecret("v")}}}
	cache := newTestCache(resolver)
	if _, err := cache.get("agv_token"); err != nil {
		t.Fatalf("get: %v", err)
	}

	resolver.err = &api.APIError{StatusCode: 503}
	cache.refresh()
	if len(cache.entries) != 1 {
		t.Fatal("an unreachable Infisical should not drop the session immediately")
	}

	key := sessionKey("agv_token")
	cache.entries[key].fetchedAt = time.Now().Add(-(unreachableGraceIntervals + 1) * time.Minute)
	cache.refresh()
	if len(cache.entries) != 0 {
		t.Fatal("the session should be dropped once the grace window has passed")
	}
}

// The bound is held by get, which evicts one before inserting one, so it is driven through get.
func TestCacheIsBounded(t *testing.T) {
	resolver := &stubResolver{result: &resolveResult{SessionID: "s1", Services: []*resolvedService{serviceWithSecret("v")}}}
	cache := newTestCache(resolver)

	for i := 0; i < maxSessionCacheEntries+50; i++ {
		if _, err := cache.get(fmt.Sprintf("agv_%d", i)); err != nil {
			t.Fatalf("get %d: %v", i, err)
		}
	}

	if len(cache.entries) != maxSessionCacheEntries {
		t.Fatalf("cache holds %d entries, want the cap of %d", len(cache.entries), maxSessionCacheEntries)
	}
	if len(cache.tokens) != maxSessionCacheEntries {
		t.Fatalf("token map holds %d entries, want %d", len(cache.tokens), maxSessionCacheEntries)
	}
}

func TestEvictionPrefersAnIdleSession(t *testing.T) {
	cache := newTestCache(&stubResolver{})
	for i := 0; i < maxSessionCacheEntries; i++ {
		cache.entries[sessionKey(fmt.Sprintf("k%d", i))] = &sessionEntry{lastSeen: time.Now()}
	}
	idle := sessionKey("idle")
	cache.entries[idle] = &sessionEntry{lastSeen: time.Now().Add(-(sessionInactiveTTL + time.Minute))}

	cache.mu.Lock()
	cache.evictIfFullLocked()
	cache.mu.Unlock()

	if _, ok := cache.entries[idle]; ok {
		t.Fatal("the idle session survived and an active one was evicted instead")
	}
	if len(cache.entries) != maxSessionCacheEntries {
		t.Fatalf("cache holds %d entries after eviction, want %d", len(cache.entries), maxSessionCacheEntries)
	}
}

func TestStaleEntryIsNotServedFromTheCache(t *testing.T) {
	resolver := &stubResolver{result: &resolveResult{SessionID: "s1", Services: []*resolvedService{serviceWithSecret("old")}}}
	cache := newTestCache(resolver)

	if _, err := cache.get("agv_tok"); err != nil {
		t.Fatalf("first get: %v", err)
	}

	key := sessionKey("agv_tok")
	cache.mu.Lock()
	cache.entries[key].fetchedAt = time.Now().Add(-cache.grace() - time.Second)
	cache.mu.Unlock()

	resolver.result = &resolveResult{SessionID: "s1", Services: []*resolvedService{serviceWithSecret("fresh")}}
	svcs, err := cache.get("agv_tok")
	if err != nil {
		t.Fatalf("stale get: %v", err)
	}
	if resolver.calls != 2 || string(svcs[0].credential.value) != "fresh" {
		t.Fatalf("a stale entry must be re-resolved, got %d calls and %q", resolver.calls, svcs[0].credential.value)
	}

	cache.mu.Lock()
	cache.entries[key].fetchedAt = time.Now().Add(-cache.grace() - time.Second)
	cache.mu.Unlock()
	resolver.err = errors.New("control plane hung")
	if _, err := cache.get("agv_tok"); err == nil {
		t.Fatal("a stale entry that cannot be re-resolved must not be served")
	}
}

// Only the refusals resolve answers by contract end a session. A 400, 403 or 422, or a 404 that is not
// Infisical's NotFound, cannot come from resolve itself, so it is a proxy-side fault or a middlebox and rides
// the grace window like an outage.
func TestRefreshTreatsOnlyTheContractRefusalsAsTerminal(t *testing.T) {
	for _, tc := range []struct {
		status int
		name   string
		kept   bool
	}{
		{401, infisicalUnauthorizedName, false}, {404, infisicalNotFoundName, false},
		{401, "", true}, {401, "Unauthorized", true},
		{404, "", true}, {404, "Not Found", true},
		{400, "", true}, {403, "", true}, {405, "", true}, {407, "", true}, {422, "", true},
		{408, "", true}, {429, "", true}, {500, "", true}, {502, "", true},
	} {
		resolver := &stubResolver{result: &resolveResult{SessionID: "s1", Services: []*resolvedService{serviceWithSecret("v")}}}
		cache := newTestCache(resolver)
		if _, err := cache.get("tok"); err != nil {
			t.Fatal(err)
		}
		resolver.err = &api.APIError{StatusCode: tc.status, Name: tc.name}
		cache.refresh()
		_, kept := cache.get("tok")
		if (kept == nil) != tc.kept {
			t.Fatalf("status %d %q: credential still served = %v, want %v", tc.status, tc.name, kept == nil, tc.kept)
		}
	}
}

func TestARejectedProxyTokenDropsTheSessionButIsNotASessionVerdict(t *testing.T) {
	err := &api.APIError{StatusCode: 401, Name: proxyTokenRejectedName, ErrorMessage: "Agent Vault proxy token has been revoked"}
	if isSessionGone(err) {
		t.Fatal("a rejected proxy token was read as the session being gone")
	}
	if !isProxyTokenRejected(err) {
		t.Fatal("the named 401 was not recognised")
	}

	resolver := &stubResolver{result: &resolveResult{SessionID: "s1", Services: []*resolvedService{serviceWithSecret("v")}}}
	cache := newTestCache(resolver)
	if _, e := cache.get("tok"); e != nil {
		t.Fatal(e)
	}
	resolver.err = err
	cache.refresh()
	if _, e := cache.get("tok"); e == nil {
		t.Fatal("the credential kept flowing after the proxy's own token was rejected")
	}
}

func TestAnUnnamed401StillEndsTheSession(t *testing.T) {
	if !isSessionGone(&api.APIError{StatusCode: 401, Name: "UnauthorizedError", ErrorMessage: "Session revoked"}) {
		t.Fatal("a plain 401 from an older server must still end the session")
	}
}

func TestConcurrentMissesForOneSessionShareOneResolve(t *testing.T) {
	resolver := &stubResolver{result: &resolveResult{SessionID: "s1"}, delay: 100 * time.Millisecond}
	cache := newTestCache(resolver)

	var wg sync.WaitGroup
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if _, err := cache.get("same-token"); err != nil {
				t.Error(err)
			}
		}()
	}
	wg.Wait()
	if got := resolver.callCount(); got != 1 {
		t.Fatalf("five concurrent misses made %d resolves, want 1", got)
	}
}

func TestRefreshRunsSessionsInParallel(t *testing.T) {
	resolver := &stubResolver{result: &resolveResult{SessionID: "s1"}, delay: 100 * time.Millisecond}
	cache := newTestCache(resolver)
	for i := 0; i < refreshParallelism; i++ {
		if _, err := cache.get(fmt.Sprintf("tok-%d", i)); err != nil {
			t.Fatal(err)
		}
	}

	start := time.Now()
	cache.refresh()
	if took := time.Since(start); took > 4*resolver.delay {
		t.Fatalf("refreshing %d sessions took %s, which is serial; want about one round trip", refreshParallelism, took)
	}
}

func TestOnlyOneRefreshRunsAtATime(t *testing.T) {
	resolver := &stubResolver{result: &resolveResult{SessionID: "s1"}, delay: 200 * time.Millisecond}
	cache := newTestCache(resolver)
	if _, err := cache.get("tok"); err != nil {
		t.Fatal(err)
	}
	before := resolver.callCount()

	cache.refreshInBackground()
	cache.refreshInBackground()
	time.Sleep(50 * time.Millisecond)
	if !cache.refreshing.Load() {
		t.Fatal("the background refresh should still be running")
	}
	time.Sleep(300 * time.Millisecond)
	if got := resolver.callCount() - before; got != 1 {
		t.Fatalf("two back-to-back background refreshes made %d resolves, want 1", got)
	}
}

func TestADefinitiveRefusalIsNotReResolvedEveryRequest(t *testing.T) {
	resolver := &stubResolver{err: &api.APIError{StatusCode: 404, Name: infisicalNotFoundName}}
	cache := newTestCache(resolver)

	for i := 0; i < 20; i++ {
		if _, err := cache.get("agv_dead"); err == nil {
			t.Fatal("a refused session resolved")
		}
	}
	if got := resolver.callCount(); got != 1 {
		t.Fatalf("20 requests on a dead session made %d resolves, want 1", got)
	}

	// A different dead token is its own resolve: the memory is per session, not global.
	_, _ = cache.get("agv_other_dead")
	if got := resolver.callCount(); got != 2 {
		t.Fatalf("a second token should resolve once more, got %d total", got)
	}
}

func TestAnOutageIsNotRememberedAsARefusal(t *testing.T) {
	for name, err := range map[string]error{
		"502":           &api.APIError{StatusCode: 502},
		"429":           &api.APIError{StatusCode: 429},
		"middlebox 403": &api.APIError{StatusCode: 403},
		"timeout":       errors.New("context deadline exceeded"),
	} {
		resolver := &stubResolver{err: err}
		cache := newTestCache(resolver)
		for i := 0; i < 5; i++ {
			_, _ = cache.get("agv_tok")
		}
		if got := resolver.callCount(); got != 5 {
			t.Fatalf("%s: %d resolves for 5 requests, an outage must not be cached", name, got)
		}
	}
}

func TestARefusalExpires(t *testing.T) {
	resolver := &stubResolver{err: &api.APIError{StatusCode: 404, Name: infisicalNotFoundName}}
	cache := newTestCache(resolver)
	_, _ = cache.get("agv_dead")
	cache.mu.Lock()
	entry := cache.refused[sessionKey("agv_dead")]
	entry.until = time.Now().Add(-time.Second)
	cache.refused[sessionKey("agv_dead")] = entry
	cache.mu.Unlock()
	_, _ = cache.get("agv_dead")
	if got := resolver.callCount(); got != 2 {
		t.Fatalf("an expired refusal should resolve again, got %d resolves", got)
	}
}

func TestARejectedProxyTokenIsNotReResolvedEveryRequest(t *testing.T) {
	resolver := &stubResolver{err: &api.APIError{StatusCode: 401, Name: proxyTokenRejectedName}}
	cache := newTestCache(resolver)
	for i := 0; i < 20; i++ {
		_, _ = cache.get("agv_tok")
	}
	if got := resolver.callCount(); got != 1 {
		t.Fatalf("20 requests against a revoked proxy made %d resolves, want 1", got)
	}
}

package gatewayv2

import (
	"errors"
	"fmt"
	"os"
	"strings"

	"github.com/Infisical/infisical-merge/packages/api"
	"github.com/go-resty/resty/v2"
)

// LoginGatewayWithKubernetes exchanges the pod's projected service account token for a
// GATEWAY_ACCESS_TOKEN. tokenPath defaults to the standard projected-token mount when empty.
func LoginGatewayWithKubernetes(httpClient *resty.Client, gatewayID string, tokenPath string) (string, error) {
	if gatewayID == "" {
		return "", errors.New("--gateway-id is required when --enroll-method=kubernetes")
	}

	if tokenPath == "" {
		tokenPath = KUBERNETES_SERVICE_ACCOUNT_TOKEN_PATH
	}

	tokenBytes, err := os.ReadFile(tokenPath)
	if err != nil {
		if os.IsNotExist(err) {
			return "", fmt.Errorf("no Kubernetes service account token found at %s. --enroll-method=kubernetes requires the gateway to run inside a Kubernetes pod, or --service-account-token-path pointing at a projected token", tokenPath)
		}
		return "", fmt.Errorf("unable to read Kubernetes service account token at %s: %w", tokenPath, err)
	}

	jwt := strings.TrimSpace(string(tokenBytes))
	if jwt == "" {
		return "", fmt.Errorf("the Kubernetes service account token at %s is empty", tokenPath)
	}

	resp, err := api.CallGatewayLogin(httpClient, api.KubernetesAuthLoginGatewayRequest{
		Method:    EnrollMethodKubernetes,
		GatewayID: gatewayID,
		JWT:       jwt,
	})
	if err != nil {
		return "", err
	}

	return resp.AccessToken, nil
}

package oracle

import (
	"bytes"
	"encoding/hex"
	"fmt"
	"strconv"
)

type authKVPCodec struct {
	name string
	get  func(payload []byte, key string) (string, error)
	set  func(payload []byte, key, newValue string) ([]byte, error)
}

var (
	ociCodec  = authKVPCodec{name: "oci", get: ociGetValue, set: ociSetValue}
	thinCodec = authKVPCodec{name: "thin", get: thinGetValue, set: thinSetValue}
)

func codecFor(payload []byte) (authKVPCodec, error) {
	if ociHasKey(payload, "AUTH_SESSKEY") {
		return ociCodec, nil
	}
	if thinHasKey(payload, "AUTH_SESSKEY") {
		return thinCodec, nil
	}
	return authKVPCodec{}, fmt.Errorf("payload carries no readable AUTH_SESSKEY")
}

func (c authKVPCodec) valueOrEmpty(payload []byte, key string) string {
	value, err := c.get(payload, key)
	if err != nil {
		return ""
	}
	return value
}

const (
	defaultPbkdf2VGenCount = 4096
	defaultPbkdf2SDerCount = 3
	maxPbkdf2VGenCount     = 1_000_000
	maxPbkdf2SDerCount     = 1_000
)

func pbkdf2Count(raw string, fallback, limit int) (int, error) {
	if raw == "" {
		return fallback, nil
	}
	n, err := strconv.Atoi(raw)
	if err != nil || n == 0 {
		return fallback, nil
	}
	if n < 0 || n > limit {
		return 0, fmt.Errorf("target requested a PBKDF2 work factor of %d, outside the supported range 1 to %d", n, limit)
	}
	return n, nil
}

func translatePhase1ResponseInPlace(payload []byte, realPassword string) (*ProxyAuthState, []byte, error) {
	c, cerr := codecFor(payload)
	if cerr != nil {
		return nil, nil, cerr
	}
	eSessKey := c.valueOrEmpty(payload, "AUTH_SESSKEY")
	vfrData := c.valueOrEmpty(payload, "AUTH_VFR_DATA")
	if eSessKey == "" || vfrData == "" {
		return nil, nil, fmt.Errorf("upstream phase 1 missing AUTH_SESSKEY or AUTH_VFR_DATA")
	}

	salt, err := hex.DecodeString(vfrData)
	if err != nil {
		return nil, nil, fmt.Errorf("decode salt: %w", err)
	}
	vGen, err := pbkdf2Count(c.valueOrEmpty(payload, "AUTH_PBKDF2_VGEN_COUNT"), defaultPbkdf2VGenCount, maxPbkdf2VGenCount)
	if err != nil {
		return nil, nil, err
	}
	sDer, err := pbkdf2Count(c.valueOrEmpty(payload, "AUTH_PBKDF2_SDER_COUNT"), defaultPbkdf2SDerCount, maxPbkdf2SDerCount)
	if err != nil {
		return nil, nil, err
	}

	realKey, _, err := deriveServerKey(realPassword, salt, vGen)
	if err != nil {
		return nil, nil, fmt.Errorf("derive real key: %w", err)
	}
	placeholderKey, _, err := deriveServerKey(ProxyPasswordPlaceholder, salt, vGen)
	if err != nil {
		return nil, nil, fmt.Errorf("derive placeholder key: %w", err)
	}

	serverSessKey, err := decryptSessionKey(false, realKey, eSessKey)
	if err != nil {
		return nil, nil, fmt.Errorf("decrypt upstream server session key: %w", err)
	}
	newESessKey, err := encryptSessionKey(false, placeholderKey, serverSessKey)
	if err != nil {
		return nil, nil, fmt.Errorf("re-encrypt server session key: %w", err)
	}

	rebuilt, err := c.set(payload, "AUTH_SESSKEY", newESessKey)
	if err != nil {
		return nil, nil, fmt.Errorf("rewrite AUTH_SESSKEY: %w", err)
	}

	return &ProxyAuthState{
		Salt:            salt,
		Pbkdf2CSKSalt:   c.valueOrEmpty(payload, "AUTH_PBKDF2_CSK_SALT"),
		Pbkdf2VGenCount: vGen,
		Pbkdf2SDerCount: sDer,
		RealKey:         realKey,
		PlaceholderKey:  placeholderKey,
		ServerSessKey:   serverSessKey,
	}, rebuilt, nil
}

func translatePhase2RequestInPlace(payload []byte, state *ProxyAuthState, realPassword string) ([]byte, error) {
	c, cerr := codecFor(payload)
	if cerr != nil {
		return nil, cerr
	}
	eClientSessKey := c.valueOrEmpty(payload, "AUTH_SESSKEY")
	ePassword := c.valueOrEmpty(payload, "AUTH_PASSWORD")
	if eClientSessKey == "" || ePassword == "" {
		return nil, fmt.Errorf("client phase 2 missing AUTH_SESSKEY or AUTH_PASSWORD")
	}

	clientSessKey, err := decryptSessionKey(false, state.PlaceholderKey, eClientSessKey)
	if err != nil {
		return nil, fmt.Errorf("decrypt client session key: %w", err)
	}
	if len(clientSessKey) != len(state.ServerSessKey) {
		return nil, fmt.Errorf("client session key length mismatch: got %d want %d", len(clientSessKey), len(state.ServerSessKey))
	}
	newEClientSessKey, err := encryptSessionKey(false, state.RealKey, clientSessKey)
	if err != nil {
		return nil, fmt.Errorf("re-encrypt client session key: %w", err)
	}

	encKey, err := deriveProxyPasswordEncKey(clientSessKey, state.ServerSessKey, state.Pbkdf2CSKSalt, state.Pbkdf2SDerCount)
	if err != nil {
		return nil, fmt.Errorf("derive enc key: %w", err)
	}
	decoded, err := decryptSessionKey(true, encKey, ePassword)
	if err != nil {
		return nil, fmt.Errorf("decrypt client password: %w", err)
	}
	if len(decoded) <= 16 || string(decoded[16:]) != ProxyPasswordPlaceholder {
		return nil, fmt.Errorf("password mismatch")
	}
	newEPassword, err := encryptPassword([]byte(realPassword), encKey, true)
	if err != nil {
		return nil, fmt.Errorf("encrypt real password: %w", err)
	}

	rebuilt, err := c.set(payload, "AUTH_SESSKEY", newEClientSessKey)
	if err != nil {
		return nil, fmt.Errorf("rewrite AUTH_SESSKEY: %w", err)
	}
	rebuilt, err = c.set(rebuilt, "AUTH_PASSWORD", newEPassword)
	if err != nil {
		return nil, fmt.Errorf("rewrite AUTH_PASSWORD: %w", err)
	}
	return rebuilt, nil
}

const authRequestProbeUser = "PROBE"

func indexOfAuthRequestMatching(payload []byte, expectedSubOp byte, accepts func([]byte) bool) int {
	firstKey := bytes.Index(payload, []byte("AUTH_"))
	if firstKey < 0 {
		return -1
	}
	first := -1
	for offset := 0; offset+1 < firstKey; offset++ {
		if payload[offset] != TTCMsgAuthRequest || payload[offset+1] != expectedSubOp {
			continue
		}
		if first < 0 {
			first = offset
		}
		if accepts != nil && accepts(payload[offset:]) {
			return offset
		}
	}
	return first
}

func indexOfAuthRequest(payload []byte, expectedSubOp byte) int {
	thin := func(b []byte) bool {
		_, err := rewriteAuthRequestUser(b, expectedSubOp, authRequestProbeUser)
		return err == nil
	}
	if offset := indexOfAuthRequestMatching(payload, expectedSubOp, thin); offset >= 0 && thin(payload[offset:]) {
		return offset
	}
	oci := func(b []byte) bool {
		_, err := ociRewriteAuthRequestUser(b, authRequestProbeUser)
		return err == nil
	}
	return indexOfAuthRequestMatching(payload, expectedSubOp, oci)
}

func ociContainsAuthRequest(payload []byte, expectedSubOp byte) bool {
	return indexOfAuthRequest(payload, expectedSubOp) >= 0
}

func rewriteBundledUsername(payload []byte, expectedSubOp byte, newUser string) ([]byte, bool) {
	offset := indexOfAuthRequest(payload, expectedSubOp)
	if offset < 0 {
		return payload, false
	}
	rewritten, err := rewriteAuthRequestUser(payload[offset:], expectedSubOp, newUser)
	if err != nil {
		rewritten, err = ociRewriteAuthRequestUser(payload[offset:], newUser)
	}
	if err != nil {
		return payload, false
	}
	return append(append([]byte{}, payload[:offset]...), rewritten...), true
}

