// limitListener must cap concurrent accepted connections: at capacity, Accept does not yield a new
// connection until a previously accepted one is closed and frees its slot.
func TestLimitListenerCapsConcurrentConns(t *testing.T) {
	base, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer base.Close()

	ll := newLimitListener(base, 1)
	addr := base.Addr().String()

	accepted := make(chan net.Conn, 4)
	go func() {
		for {
			c, err := ll.Accept()
			if err != nil {
				return
			}
			accepted <- c
		}
	}()

	c1, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	defer c1.Close()

	var a1 net.Conn
	select {
	case a1 = <-accepted:
	case <-time.After(2 * time.Second):
		t.Fatal("first connection was not accepted")
	}

	// The TCP connect may complete via the kernel backlog, but Accept must not yield it while at capacity.
	c2, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	defer c2.Close()
	select {
	case <-accepted:
		t.Fatal("second connection accepted while at capacity")
	case <-time.After(300 * time.Millisecond):
	}

	// Freeing the first slot lets the second through.
	_ = a1.Close()
	select {
	case a2 := <-accepted:
		_ = a2.Close()
	case <-time.After(2 * time.Second):
		t.Fatal("second connection not accepted after slot freed")
	}
}

package agentvault

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

type deadlineWriter struct {
	http.ResponseWriter
	deadlines []time.Time
}

func (d *deadlineWriter) SetWriteDeadline(t time.Time) error {
	d.deadlines = append(d.deadlines, t)
	return nil
}

func TestEachStreamedChunkPushesTheWriteDeadlineOut(t *testing.T) {
	rec := &deadlineWriter{ResponseWriter: httptest.NewRecorder()}
	w := &flushingWriter{ResponseWriter: rec, rc: http.NewResponseController(rec)}

	for i := 0; i < 3; i++ {
		if _, err := io.WriteString(w, "chunk\n"); err != nil {
			t.Fatalf("write %d: %v", i, err)
		}
		time.Sleep(2 * time.Millisecond)
	}

	if len(rec.deadlines) != 3 {
		t.Fatalf("expected one deadline per chunk, got %d", len(rec.deadlines))
	}
	for i := 1; i < len(rec.deadlines); i++ {
		if !rec.deadlines[i].After(rec.deadlines[i-1]) {
			t.Fatalf("chunk %d did not push the deadline out: %v then %v", i, rec.deadlines[i-1], rec.deadlines[i])
		}
	}
	if got := time.Until(rec.deadlines[len(rec.deadlines)-1]); got < streamIdleTimeout-time.Second {
		t.Fatalf("last deadline is only %v away, want about %v", got, streamIdleTimeout)
	}
}

